sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '') {
		return;
	}

	var currentCity = g_form.getValue('city');

	if (currentCity === '') return;

	var ga = new GlideAjax("x_1590365_worksp_0.WorkspacePlanningUtils");
	ga.addParam("sysparm_name", "validateSameCityAndState");
	ga.addParam("sysparm_base_city", currentCity);
	ga.addParam("sysparm_base_state", newValue);

	ga.getXMLAnswer(function (response) {
		if (!response) return;

		var objResponse = JSON.parse(response);
		var infoMsg = objResponse.message;

		if (infoMsg) {
			g_form.clearValue('state');
			g_form.clearValue('city');
			g_form.showFieldMsg('state', infoMsg, 'error');
		} else {
			return;
		}
	});

}
